void ObjectGuardingHelper::setGuardedObject(Object *guarded)
{
	if (m_guardedID)
	{
		Object *previous = TheGameLogic->findObjectByID(m_guardedID);
		if (!previous)
			m_guardedID = (ObjectID)0;
		else
			stopGuarding(previous);
	}
	if (guarded)
	{
		m_guardedID = guarded->getID();
		guarded->addGuarder(getObject());
		setGuardStatus();
	}
}

